-- 纯净版内容导入基准 v1
-- 仅人工审核后执行；项目启动不自动执行本文件。
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;
DELETE FROM EquipmentTemplates;
DELETE FROM MonsterTemplates;
DELETE FROM MapTemplates;
DELETE FROM ItemTemplates;
CREATE TABLE IF NOT EXISTS EquipmentEnhanceRuleConfigs (GID INTEGER PRIMARY KEY AUTOINCREMENT,MinEquipmentLevel INTEGER NOT NULL DEFAULT 1,MaxEquipmentLevel INTEGER NOT NULL DEFAULT 30,MaterialItemId TEXT NOT NULL,MaterialCount INTEGER NOT NULL DEFAULT 1,GoldCost INTEGER NOT NULL DEFAULT 0,SuccessRate INTEGER NOT NULL DEFAULT 100,AttributeGrowthPercent INTEGER NOT NULL DEFAULT 10,MaxEnhanceLevel INTEGER NOT NULL DEFAULT 15,SortOrder INTEGER NOT NULL DEFAULT 0,IsEnabled INTEGER NOT NULL DEFAULT 1,SeedKey TEXT NULL,IsBuiltIn INTEGER NOT NULL DEFAULT 0,BuiltInVersion TEXT NULL,LastUpdateTime TEXT NOT NULL DEFAULT '2000-01-01 00:00:00');
CREATE TABLE IF NOT EXISTS EquipmentDecomposeRuleConfigs (GID INTEGER PRIMARY KEY AUTOINCREMENT,Quality INTEGER NOT NULL DEFAULT 1,MaterialItemId TEXT NOT NULL,MinQuantity INTEGER NOT NULL DEFAULT 1,MaxQuantity INTEGER NOT NULL DEFAULT 1,SortOrder INTEGER NOT NULL DEFAULT 0,IsEnabled INTEGER NOT NULL DEFAULT 1,SeedKey TEXT NULL,IsBuiltIn INTEGER NOT NULL DEFAULT 0,BuiltInVersion TEXT NULL,LastUpdateTime TEXT NOT NULL DEFAULT '2000-01-01 00:00:00');
CREATE TABLE IF NOT EXISTS EquipmentRerollCostRuleConfigs (GID INTEGER PRIMARY KEY AUTOINCREMENT,MinEquipmentLevel INTEGER NOT NULL DEFAULT 1,MaxEquipmentLevel INTEGER NOT NULL DEFAULT 30,MaterialItemId TEXT NOT NULL,MaterialCount INTEGER NOT NULL DEFAULT 1,GoldCost INTEGER NOT NULL DEFAULT 0,ExtraMaterialPerLockedLine INTEGER NOT NULL DEFAULT 0,ExtraGoldPerLockedLine INTEGER NOT NULL DEFAULT 0,SortOrder INTEGER NOT NULL DEFAULT 0,IsEnabled INTEGER NOT NULL DEFAULT 1,SeedKey TEXT NULL,IsBuiltIn INTEGER NOT NULL DEFAULT 0,BuiltInVersion TEXT NULL,LastUpdateTime TEXT NOT NULL DEFAULT '2000-01-01 00:00:00');
COMMIT;
PRAGMA foreign_keys = ON;
